        runOnMainSync(()->{try{mode.invoke(activity,false);}catch(Exception e){throw new IllegalStateException(e);}});await(()->!camera.isBusy(),15000);Method editor=MainActivity.class.getDeclaredMethod("watermarkStudio");editor.setAccessible(true);runOnMainSync(()->{try{editor.invoke(activity);}catch(Exception e){throw new IllegalStateException(e);}});await(()->node(getUiAutomation().getRootInActiveWindow(),"Photos")!=null,3000);for(String label:new String[]{"Photos","Videos"}){android.view.accessibility.AccessibilityNodeInfo toggle=node(getUiAutomation().getRootInActiveWindow(),label);if(toggle.isChecked()&&!toggle.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))throw new IOException("Watermark switch click failed");}android.content.SharedPreferences prefs=getTargetContext().getSharedPreferences("settings",0);await(()->!prefs.getBoolean("watermarkPhoto",true)&&!prefs.getBoolean("watermarkVideo",true),3000);WatermarkSettings mark=(WatermarkSettings)field(preview,"watermark");if(mark.photo||mark.video)throw new IOException("Preview retained watermark after OFF");node(getUiAutomation().getRootInActiveWindow(),"Close watermark settings").performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK);cases.put(new JSONObject().put("test","watermark_switches_off_without_save_updates_preview_and_preferences").put("passed",true));report.put("failed",0);persist(report);
